//ContextMenuStrip and numericUpDownpublic class ToolStripNumericUpDown : ToolStripControlHost    {        // Call the base constructor passing in a MonthCalendar instance.        public ToolStripNumericUpDown() : base(new NumericUpDown()) { }        public NumericUpDown NumericUpDown        {            get { return Control as NumericUpDown; }        }        public decimal value        {            get { return NumericUpDown.Value; }            set { NumericUpDown.Value = value; }        }    }